import { byXPath, type Locator } from './PageElement';

/**
 * A heading (h1-h6, a table header, a label, a legend, a caption, a dt) whose whole text is exactly
 * one of these, whitespace aside: Headings.named('Contact Us'). Its whole text counts, child elements
 * included, so "Contact <strong>Us</strong>" and "<span>Automation</span>Exercise" are found;
 * cy.contains() matches the deepest element and would find the <strong>. Several texts: any of them
 * ('Dive deeper', 'Dive Deeper').
 */
export const Headings = {
  named(...texts: string[]): Locator {
    return byXPath(Headings.xpath(...texts));
  },

  /**
   * A heading that is the page's own title, with these fixed words around it, read from the page's own
   * title: Headings.titled('', ' Pokédex entry | Dex') finds "Pikachu" on a page titled "Pikachu
   * Pokédex entry | Dex". What a page proves itself by when no heading is on every page of its type.
   */
  titled(before: string, after: string): Locator {
    return byXPath(Headings.titledXPath(before, after));
  },

  /** The XPath of Headings.titled(). */
  titledXPath(before: string, after: string): string {
    const title = spaced('//head/title');
    const whole = `${spaced('.')}=${title}`;
    if (!before && !after) return `//*[${TAGS}][${whole}]`;
    return `//*[${TAGS}][${whole} or concat(${literal(before)}, ${spaced('.')}, ${literal(after)})=${title}]`;
  },

  /** The XPath: //*[self::h1 or ...][normalize-space(.)='Contact Us'], odd spaces made plain. */
  xpath(...texts: string[]): string {
    const any = texts.map((t) => `${spaced('.')}=${literal(t)} or ${spaced('text()')}=${literal(t)}`).join(' or ');
    return `//*[${TAGS}][${any}]`;
  },
};

const TAGS = 'self::h1 or self::h2 or self::h3 or self::h4 or self::h5 or self::h6 or self::th or self::legend or self::label or self::caption or self::dt';

/** Spaces normalize-space() keeps (a non-breaking space: "GSA&nbsp;Multiple"), made plain. */
const ODD_SPACES = '\u00A0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF';

/** normalize-space() of an XPath expression, with every kind of space counted as a space. */
function spaced(expr: string): string {
  return `normalize-space(translate(${expr},'${ODD_SPACES}','${' '.repeat(ODD_SPACES.length)}'))`;
}

/** A string as an XPath literal: 'x', "it's", or concat() when it holds both quotes. */
export function literal(s: string): string {
  if (!s.includes("'")) return `'${s}'`;
  if (!s.includes('"')) return `"${s}"`;
  return `concat('${s.split("'").join(`', "'", '`)}')`;
}

